// -----------------------------------------------------------------------------
// Secrets generated by the integration itself, persisted in /data.
//
//   - credential_secret: key Node-RED encrypts flows_cred.json with. It must
//     never change, or every credential stored in the flows is lost;
//   - event_token: bearer token Node-RED presents to the event endpoint of
//     the integration (see src/eventServer.js);
//   - password_salt: salt of the scrypt hash of the admin password written
//     into settings.js. Stable, so the same password gives the same file and
//     Node-RED is only restarted when something really changed.
//
// /data is the only writable volume of the container (read-only rootfs). The
// file is created owner-only and never logged.
// -----------------------------------------------------------------------------

import { randomBytes } from 'node:crypto';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';

const FILE_NAME = 'secrets.json';

const GENERATORS = {
  credential_secret: () => randomBytes(32).toString('hex'),
  event_token: () => randomBytes(32).toString('hex'),
  password_salt: () => randomBytes(16).toString('hex'),
};

/**
 * Read the secrets, generating (and saving) the missing ones.
 * @param {string} dataDir the integration data folder (/data in production)
 */
export async function loadSecrets(dataDir) {
  const filePath = path.join(dataDir, FILE_NAME);
  let stored = {};
  try {
    stored = JSON.parse(await readFile(filePath, 'utf8'));
  } catch (err) {
    if (err.code !== 'ENOENT') {
      // A corrupted file would silently regenerate the credential secret and
      // make the stored flow credentials unreadable: refuse instead.
      throw new Error(`Unable to read ${filePath}: ${err.message}`, { cause: err });
    }
  }
  const secrets = { ...stored };
  let changed = false;
  for (const [key, generate] of Object.entries(GENERATORS)) {
    if (typeof secrets[key] !== 'string' || secrets[key].length === 0) {
      secrets[key] = generate();
      changed = true;
    }
  }
  if (changed) {
    await mkdir(dataDir, { recursive: true });
    await writeFile(filePath, `${JSON.stringify(secrets, null, 2)}\n`, { mode: 0o600 });
  }
  return secrets;
}
